#!/usr/bin/env sh
# Verify one release bundle using the SHA256SUMS.txt generated by the release workflow.
set -eu
if [ "$#" -ne 2 ]; then
  echo "Usage: verify-checksum.sh <archive-path> <SHA256SUMS.txt>" >&2
  exit 2
fi
archive=$1
sums=$2
name=$(basename "$archive")
expected=$(awk -v wanted="$name" '$2 == wanted { print $1; exit }' "$sums")
if [ -z "$expected" ]; then
  echo "No SHA-256 entry found for $name in $sums" >&2
  exit 1
fi
if command -v sha256sum >/dev/null 2>&1; then
  actual=$(sha256sum "$archive" | awk '{print $1}')
else
  actual=$(shasum -a 256 "$archive" | awk '{print $1}')
fi
if [ "$actual" != "$expected" ]; then
  echo "SHA-256 mismatch for $name" >&2
  echo "expected: $expected" >&2
  echo "actual:   $actual" >&2
  exit 1
fi
echo "PASS: SHA-256 verified for $name"
